package chat

import java.util.concurrent.{ConcurrentHashMap, CountDownLatch}
import java.util.concurrent.atomic.AtomicBoolean
import scala.collection.JavaConverters._
import org.eclipse.jetty.server.Server
import org.eclipse.jetty.websocket.api.{Session, WebSocketAdapter}
import org.eclipse.jetty.websocket.server.WebSocketHandler
import org.eclipse.jetty.websocket.servlet.{WebSocketServletFactory, WebSocketCreator, ServletUpgradeRequest, ServletUpgradeResponse}
import org.eclipse.jetty.server.handler.{HandlerList, ResourceHandler}
import org.eclipse.jetty.servlet.{ServletContextHandler, ServletHolder}
import javax.servlet.http.{HttpServlet, HttpServletRequest, HttpServletResponse}

object ChatServer {
  val sessions = new ConcurrentHashMap[String, Session]()
  val shutdownFlag = new AtomicBoolean(false)
  val shutdownLatch = new CountDownLatch(1)

  // Message sanitization pipeline
  object MessagePipeline {
    // Stage 1: Normalize unicode
    def normalizeUnicode(input: String): String = {
      java.text.Normalizer.normalize(input, java.text.Normalizer.Form.NFC)
    }

    // Stage 2: Entity encoding for HTML context
    def encodeForHtml(input: String): String = {
      input
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
        .replace("\"", "&quot;")
        .replace("'", "&#x27;")
    }

    // Stage 3: Build safe message envelope
    def buildEnvelope(username: String, content: String, msgType: String): String = {
      val timestamp = System.currentTimeMillis()
      msgType match {
        case "system" =>
          s"""{ "type": "system", "timestamp": $timestamp, "content": "${encodeForJson(content)}" }"""
        case "chat" =>
          s"""{ "type": "chat", "timestamp": $timestamp, "user": "${encodeForJson(username)}", "content": "${encodeForJson(content)}" }"""
        case "rendered" =>
          // Pre-rendered HTML messages from server (trusted)
          s"""{ "type": "rendered", "timestamp": $timestamp, "html": "${encodeForJson(content)}" }"""
        case _ =>
          s"""{ "type": "unknown", "timestamp": $timestamp, "content": "${encodeForJson(content)}" }"""
      }
    }

    def encodeForJson(input: String): String = {
      input
        .replace("\\", "\\\\")
        .replace("\"", "\\\"")
        .replace("\n", "\\n")
        .replace("\r", "\\r")
        .replace("\t", "\\t")
    }

    // Full pipeline for user messages
    def processUserMessage(username: String, rawContent: String): String = {
      val normalized = normalizeUnicode(rawContent)
      val encoded = encodeForHtml(normalized)
      buildEnvelope(username, encoded, "chat")
    }

    // Pipeline for join/leave notifications
    def processNotification(username: String, action: String): String = {
      val safeUser = encodeForHtml(normalizeUnicode(username))
      val rendered = s"<span class='notification'><b>$safeUser</b> has $action the chat</span>"
      buildEnvelope("", rendered, "rendered")
    }
  }

  class ChatSocket extends WebSocketAdapter {
    private var username: String = _

    override def onWebSocketConnect(sess: Session): Unit = {
      super.onWebSocketConnect(sess)
      val params = sess.getUpgradeRequest.getParameterMap
      username = Option(params.get("username"))
        .flatMap(l => Option(l.get(0)))
        .getOrElse("anonymous_" + sess.hashCode().toHexString)

      sessions.put(username, sess)
      broadcast(MessagePipeline.processNotification(username, "joined"))
    }

    override def onWebSocketText(message: String): Unit = {
      if (shutdownFlag.get()) {
        getSession.getRemote.sendString(
          MessagePipeline.buildEnvelope("", "Server is shutting down", "system")
        )
        return
      }

      if (message.startsWith("/nick ")) {
        val newName = message.substring(6).trim
        handleNickChange(newName)
      } else {
        val safeMessage = MessagePipeline.processUserMessage(username, message)
        broadcast(safeMessage)
      }
    }

    private def handleNickChange(newName: String): Unit = {
      val oldName = username
      sessions.remove(oldName)
      username = newName
      sessions.put(username, getSession)
      // Notify with old and new name - uses rendered type for rich formatting
      val notification = {
        val safeOld = MessagePipeline.encodeForHtml(MessagePipeline.normalizeUnicode(oldName))
        val safeNew = MessagePipeline.normalizeUnicode(newName)
        val html = s"<span class='nick-change'><b>$safeOld</b> is now known as <b>$safeNew</b></span>"
        MessagePipeline.buildEnvelope("", html, "rendered")
      }
      broadcast(notification)
    }

    override def onWebSocketClose(statusCode: Int, reason: String): Unit = {
      sessions.remove(username)
      broadcast(MessagePipeline.processNotification(username, "left"))
      super.onWebSocketClose(statusCode, reason)
    }
  }

  def broadcast(message: String): Unit = {
    sessions.values().asScala.foreach { session =>
      if (session.isOpen) {
        try {
          session.getRemote.sendString(message)
        } catch {
          case _: Exception => // connection lost
        }
      }
    }
  }

  class HealthServlet extends HttpServlet {
    override def doGet(req: HttpServletRequest, resp: HttpServletResponse): Unit = {
      resp.setContentType("application/json")
      resp.setStatus(if (shutdownFlag.get()) 503 else 200)
      resp.getWriter.write(s"""{ "status": "${if (shutdownFlag.get()) "draining" else "ok"}", "connections": ${sessions.size()} }""")
    }
  }

  def gracefulShutdown(server: Server): Unit = {
    shutdownFlag.set(true)
    val drainMsg = MessagePipeline.buildEnvelope("", "Server shutting down in 30s", "system")
    broadcast(drainMsg)
    Thread.sleep(30000)
    sessions.values().asScala.foreach { s =>
      try { s.close(1001, "Server shutdown") } catch { case _: Exception => }
    }
    server.stop()
    shutdownLatch.countDown()
  }

  def main(args: Array[String]): Unit = {
    val server = new Server(8080)
    val wsHandler = new WebSocketHandler {
      override def configure(factory: WebSocketServletFactory): Unit = {
        factory.setCreator(new WebSocketCreator {
          override def createWebSocket(req: ServletUpgradeRequest, resp: ServletUpgradeResponse): Object = {
            new ChatSocket()
          }
        })
      }
    }

    val context = new ServletContextHandler()
    context.addServlet(new ServletHolder(new HealthServlet()), "/health")

    val handlers = new HandlerList()
    handlers.setHandlers(Array(wsHandler, context))
    server.setHandler(handlers)

    Runtime.getRuntime.addShutdownHook(new Thread(() => gracefulShutdown(server)))

    server.start()
    println("Chat server started on :8080")
    shutdownLatch.await()
  }
}
